{"cards": [{"node_code": "N_a24a07f2d52b7640", "definition": "燃气轮机车中负责电能产生、分配、控制及监测的电气系统，涵盖发电机、主电路、控制电路、照明及信号等电气部件。", "boundary": "本节点聚焦于燃气轮机车内部的电气系统。边界在于区分“电气”与“机械传动”（机械齿轮、轴系归传动装置）、“动力源”（燃气轮机本体归动力装置）。若涉及电气控制逻辑与机械执行的耦合，侧重电气信号与电路归本节点。不包含非电气的机械制动或纯机械传动部件。", "includes": ["燃气轮机车发电机、主电路与控制电路设计", "电气控制系统、照明、信号及监测装置", "电气部件的绝缘、防护及检修维护技术"], "excludes": ["燃气轮机本体及其热力循环系统（归动力装置）", "机械传动齿轮、轴系及离合器（归传动装置）", "非电气的机械制动部件（归制动装置）"], "sibling_distinctions": [{"other_code": "N_9cf7d0d91f1abb31", "rule": "区分依据为能量转换形式：电气设备处理电能（发电、配电、控制）；传动装置处理机械能（扭矩传递、变速）。"}, {"other_code": "N_8efcab734d3f6eac", "rule": "区分依据为功能层级：动力装置是能量源（燃气轮机）；电气设备是能量转换与控制系统（发电机及电路）。"}], "cross_boundary_rule": "若内容涉及“电传动”整体，若侧重发电机特性与电路控制归本节点；若侧重齿轮箱机械结构归传动装置。"}, {"node_code": "N_9d26c6f9e8df72aa", "definition": "燃气轮机车中支撑车体、引导运行并缓冲冲击的走行系统，涵盖转向架、轮对、轴箱、弹簧悬挂及连接装置。", "boundary": "本节点聚焦于机车的走行部（Bogie/Running Gear）。边界在于区分“走行”与“制动”（制动执行机构归制动装置）、“传动”（动力传递路径归传动装置）。若涉及轮轨相互作用，侧重结构支撑与导向归本节点。不包含车体结构或动力源。", "includes": ["转向架结构、轮对、轴箱及轴承技术", "弹簧悬挂系统、减振装置及车钩缓冲装置", "走行部的动力学特性、磨损分析及检修维护"], "excludes": ["制动夹钳、闸瓦等制动执行部件（归制动装置）", "传动齿轮、联轴器等动力传递部件（归传动装置）", "车体钢结构及内部布局（归车体工程或总体设计）"], "sibling_distinctions": [{"other_code": "N_75ca00c2067de923", "rule": "区分依据为功能：走行部分负责支撑、导向与减振；制动装置负责减速与停车。"}, {"other_code": "N_9cf7d0d91f1abb31", "rule": "区分依据为能量路径：走行部分承载车体并引导轮轨接触；传动装置将动力从动力源传递至轮对。"}], "cross_boundary_rule": "若内容涉及“轮轨关系”，若侧重轮对结构、悬挂参数归本节点；若侧重制动时的轮轨粘着利用归制动装置。"}, {"node_code": "N_75ca00c2067de923", "definition": "燃气轮机车中用于减速、停车及保持静止的制动系统，涵盖空气制动、电制动、机械制动及控制装置。", "boundary": "本节点聚焦于机车的制动功能实现。边界在于区分“制动”与“走行”（轮对结构归走行部分）、“电气”（电制动的控制电路归电气设备，但制动执行归本节点）。若涉及制动与牵引的协调控制，侧重制动过程归本节点。不包含非制动用途的机械结构。", "includes": ["空气制动系统（风缸、阀类、管路）及电制动技术", "机械制动部件（闸瓦、盘形制动）及基础制动装置", "制动控制逻辑、防滑控制及制动性能试验"], "excludes": ["走行部结构（轮对、转向架框架，归走行部分）", "电气控制电路本身（归电气设备）", "动力源及传动系统（归动力装置、传动装置）"], "sibling_distinctions": [{"other_code": "N_9d26c6f9e8df72aa", "rule": "区分依据为功能：制动装置负责能量耗散以实现减速；走行部分负责支撑与导向。"}, {"other_code": "N_a24a07f2d52b7640", "rule": "区分依据为系统属性：制动装置侧重机械/气动执行与制动过程；电气设备侧重电能控制与电路。"}], "cross_boundary_rule": "若内容涉及“电制动”，若侧重电机作为发电机的运行特性归电气设备；若侧重制动指令、防滑控制及机械制动配合归本节点。"}]}
